<script setup>
import { computed, reactive, ref } from 'vue'

const tabs = [['setup','Set Up'],['results','结果'],['compare','layer 对比'],['gradient','梯度 Spec'],['history','历史'],['fa','FA 关联']]
const activeTab = ref('setup')
const selectedTaskId = ref(null)
const tasks = ref([])
const tclInput = ref('density::analyze -layer M1')
const tclLog = ref([])
const form = reactive({project:'',gdsName:'',layer:'M1',compareLayer:'M2',stepUm:100,widthUm:500,heightUm:500,gradientSpec:0.08})
const selectedTask = computed(() => tasks.value.find(task => task.id === selectedTaskId.value) || null)

function seededValue(seed, offset=0){let value=0;const text=`${seed}:${offset}`;for(let i=0;i<text.length;i+=1)value=(value*31+text.charCodeAt(i))>>>0;return .43+((value%900)/10000)}
function makeResult(task){const mean=seededValue(task.id),variance=.001+((task.id%13)/10000),gradient=.035+((task.id%9)/1000),pValue=.08+((task.id%7)/100);return{mean,variance,gradient,pValue,pass:gradient<=task.gradientSpec&&variance<.0025&&pValue>=.05}}
function createTask(source='form') {const id=Date.now();const task={id,name:`TASK-${String(tasks.value.length+1).padStart(3,'0')}`,project:form.project||'未命名项目',gdsName:form.gdsName||'demo.gds',layer:form.layer,compareLayer:form.compareLayer,stepUm:Number(form.stepUm),widthUm:Number(form.widthUm),heightUm:Number(form.heightUm),gradientSpec:Number(form.gradientSpec),source,createdAt:new Date().toLocaleString()};task.result=makeResult(task);tasks.value.unshift(task);selectedTaskId.value=task.id;activeTab.value='results'}
function openTask(task,tab='results'){selectedTaskId.value=task.id;activeTab.value=tab}
function runTcl(){const command=tclInput.value.trim();if(!command)return;const layerMatch=command.match(/-layer\s+(\S+)/i),stepMatch=command.match(/-step\s+(\d+(?:\.\d+)?)/i);if(layerMatch)form.layer=layerMatch[1];if(stepMatch)form.stepUm=Number(stepMatch[1]);const canCreate=/density::analyze|density::create/i.test(command);const output=canCreate?'已根据 TCL command 创建 density 分析任务。':'command 已执行。使用 density::analyze 创建任务。';tclLog.value.unshift({command,output,time:new Date().toLocaleTimeString()});if(canCreate)createTask('tcl')}
function requireTask(tab){if(!selectedTask.value){activeTab.value='setup';return}activeTab.value=tab}
</script>

<template>
  <main class="density-task-page">
    <header class="density-task-header"><div><div class="eyebrow">GDS · density · layer</div><h1>GDS Density 分析</h1><p>先在 Set Up 创建任务，再进入其他页签查看该任务的分析结果。</p></div><div v-if="selectedTask" class="current-task"><span>当前任务</span><strong>{{ selectedTask.name }}</strong><small>{{ selectedTask.project }} · {{ selectedTask.gdsName }} · {{ selectedTask.layer }}</small></div></header>
    <nav class="density-task-tabs"><button v-for="tab in tabs" :key="tab[0]" :class="{active:activeTab===tab[0]}" @click="tab[0]==='setup'?activeTab='setup':requireTask(tab[0])">{{ tab[1] }}</button></nav>

    <section v-if="activeTab==='setup'" class="task-workspace">
      <div class="task-panel setup-panel"><div class="panel-head"><div><span>SET UP</span><h2>创建 density 分析任务</h2></div><button class="primary" @click="createTask('form')">创建任务</button></div><div class="setup-grid"><label><span>项目</span><input v-model="form.project" placeholder="项目名称"></label><label><span>GDS 文件</span><input v-model="form.gdsName" placeholder="example.gds"></label><label><span>GDS layer</span><input v-model="form.layer"></label><label><span>对比 layer</span><input v-model="form.compareLayer"></label><label><span>窗口 step</span><input v-model.number="form.stepUm" type="number"><b>µm</b></label><label><span>窗口宽度</span><input v-model.number="form.widthUm" type="number"><b>µm</b></label><label><span>窗口高度</span><input v-model.number="form.heightUm" type="number"><b>µm</b></label><label><span>Gradient Spec</span><input v-model.number="form.gradientSpec" type="number" step="0.005"></label></div></div>
      <div class="task-panel tcl-panel"><div class="panel-head"><div><span>TCL COMMAND</span><h2>在 Set Up 中调用 TCL command</h2></div></div><div class="terminal-box"><div class="terminal-log"><div v-if="!tclLog.length" class="terminal-empty">示例：density::analyze -layer M1 -step 100</div><div v-for="(item,index) in tclLog" :key="index" class="terminal-row"><p><small>{{ item.time }}</small> $ {{ item.command }}</p><pre>{{ item.output }}</pre></div></div><form @submit.prevent="runTcl"><span>$</span><input v-model="tclInput" spellcheck="false"><button>运行</button></form></div></div>
      <div class="task-panel task-list-panel"><div class="panel-head"><div><span>TASKS</span><h2>已创建任务</h2></div><small>其他页签均从这里选择任务查看</small></div><div v-if="!tasks.length" class="empty-state">暂无任务。请使用上方表单或 TCL command 创建任务。</div><table v-else><thead><tr><th>任务</th><th>项目</th><th>GDS</th><th>layer</th><th>step</th><th>来源</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="task in tasks" :key="task.id" :class="{selected:task.id===selectedTaskId}"><td><strong>{{ task.name }}</strong></td><td>{{ task.project }}</td><td>{{ task.gdsName }}</td><td>{{ task.layer }}</td><td>{{ task.stepUm }} µm</td><td>{{ task.source==='tcl'?'TCL':'表单' }}</td><td><span :class="task.result.pass?'pass':'review'">{{ task.result.pass?'通过':'需检查' }}</span></td><td><button class="link-btn" @click="openTask(task)">查看结果</button></td></tr></tbody></table></div>
    </section>

    <section v-else-if="selectedTask" class="task-workspace result-layout">
      <div class="task-panel task-summary full"><div><span>任务</span><strong>{{ selectedTask.name }}</strong></div><div><span>项目</span><strong>{{ selectedTask.project }}</strong></div><div><span>GDS</span><strong>{{ selectedTask.gdsName }}</strong></div><div><span>layer</span><strong>{{ selectedTask.layer }}</strong></div><div><span>窗口</span><strong>{{ selectedTask.widthUm }} × {{ selectedTask.heightUm }} µm</strong></div></div>
      <template v-if="activeTab==='results'"><div class="metric"><span>平均 density</span><strong>{{ (selectedTask.result.mean*100).toFixed(2) }}%</strong></div><div class="metric"><span>方差</span><strong>{{ selectedTask.result.variance.toFixed(6) }}</strong></div><div class="metric"><span>均匀性 p-value</span><strong>{{ selectedTask.result.pValue.toFixed(3) }}</strong></div><div class="metric"><span>最大梯度</span><strong>{{ (selectedTask.result.gradient*100).toFixed(2) }}%</strong></div><div class="metric"><span>综合结果</span><strong :class="selectedTask.result.pass?'pass-text':'review-text'">{{ selectedTask.result.pass?'通过':'需检查' }}</strong></div><div class="task-panel full"><div class="panel-head"><div><span>RESULT</span><h2>{{ selectedTask.name }} density 结果</h2></div></div><div class="heat-demo"><i v-for="n in 120" :key="n" :style="{opacity:.35+((n*7)%60)/100}"></i></div></div></template>
      <template v-else-if="activeTab==='compare'"><div class="task-panel full"><div class="panel-head"><div><span>LAYER</span><h2>{{ selectedTask.layer }} 与 {{ selectedTask.compareLayer }} 同区域对比</h2></div></div><div class="compare-cards"><div><span>{{ selectedTask.layer }}</span><strong>{{ (selectedTask.result.mean*100).toFixed(2) }}%</strong></div><div><span>{{ selectedTask.compareLayer }}</span><strong>{{ ((selectedTask.result.mean-.012)*100).toFixed(2) }}%</strong></div><div><span>区域相关性</span><strong>0.936</strong></div></div></div></template>
      <template v-else-if="activeTab==='gradient'"><div class="task-panel full"><div class="panel-head"><div><span>SPEC</span><h2>梯度 Spec 检查</h2></div></div><div class="spec-row"><div><span>任务 Spec</span><strong>{{ selectedTask.gradientSpec }}</strong></div><div><span>实测梯度</span><strong>{{ selectedTask.result.gradient.toFixed(4) }}</strong></div><div><span>判定</span><strong :class="selectedTask.result.gradient<=selectedTask.gradientSpec?'pass-text':'review-text'">{{ selectedTask.result.gradient<=selectedTask.gradientSpec?'符合 Spec':'超出 Spec' }}</strong></div></div></div></template>
      <template v-else-if="activeTab==='history'"><div class="task-panel full"><div class="panel-head"><div><span>HISTORY</span><h2>任务与历史项目 density 对比</h2></div></div><table><thead><tr><th>项目</th><th>layer</th><th>平均 density</th><th>方差</th><th>梯度</th></tr></thead><tbody><tr><td>{{ selectedTask.project }}（当前）</td><td>{{ selectedTask.layer }}</td><td>{{ (selectedTask.result.mean*100).toFixed(2) }}%</td><td>{{ selectedTask.result.variance.toFixed(6) }}</td><td>{{ selectedTask.result.gradient.toFixed(4) }}</td></tr><tr><td>History-A</td><td>{{ selectedTask.layer }}</td><td>46.80%</td><td>0.001800</td><td>0.0610</td></tr><tr><td>History-B</td><td>{{ selectedTask.layer }}</td><td>45.10%</td><td>0.002200</td><td>0.0730</td></tr></tbody></table></div></template>
      <template v-else-if="activeTab==='fa'"><div class="task-panel full"><div class="panel-head"><div><span>FA LIBRARY</span><h2>{{ selectedTask.project }} 失效信息关联</h2></div></div><div class="empty-state">这里将使用任务中的项目 / GDS 关键字查询 FA Library，并展示对应 fail type / fail model。</div></div></template>
    </section>
  </main>
</template>

<style scoped>
.density-task-page{margin-left:272px;padding:78px 28px 48px;min-height:100vh;background:#f5f7fa;color:#1f2937}.density-task-header{display:flex;justify-content:space-between;gap:24px;align-items:flex-start;margin-bottom:18px}.density-task-header h1{margin:4px 0 6px;font-size:28px}.density-task-header p{margin:0;color:#687386;font-size:13px}.eyebrow,.panel-head span{font-size:10px;font-weight:800;letter-spacing:.12em;color:#7a8594}.current-task{min-width:260px;padding:12px 14px;border:1px solid #dfe4ea;border-radius:10px;background:#fff}.current-task span,.current-task small{display:block;color:#7b8490;font-size:10px}.current-task strong{display:block;margin:4px 0}.density-task-tabs{display:flex;gap:4px;border-bottom:1px solid #d9dee5;margin-bottom:18px}.density-task-tabs button{border:0;background:transparent;padding:10px 14px;color:#697384;font-weight:700;border-bottom:2px solid transparent}.density-task-tabs button.active{color:#17212b;border-bottom-color:#17212b}.task-workspace{display:grid;grid-template-columns:1.15fr .85fr;gap:16px}.task-panel{background:#fff;border:1px solid #dfe4ea;border-radius:10px;padding:18px}.setup-panel,.tcl-panel{min-height:360px}.task-list-panel,.full{grid-column:1/-1}.panel-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:16px}.panel-head h2{margin:3px 0 0;font-size:16px}.primary{height:36px;padding:0 16px;border:0;border-radius:7px;background:#2563eb;color:#fff;font-weight:700}.setup-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.setup-grid label{display:grid;gap:6px;position:relative}.setup-grid label span{font-size:11px;font-weight:700;color:#667085}.setup-grid input{height:38px;border:1px solid #cfd6df;border-radius:7px;padding:0 11px}.setup-grid b{position:absolute;right:9px;bottom:11px;font-size:10px;color:#98a2b3}.terminal-box{height:285px;background:#101720;border-radius:8px;color:#d8e1ea;display:flex;flex-direction:column;overflow:hidden}.terminal-log{flex:1;overflow:auto;padding:12px}.terminal-empty{color:#8190a3;font-size:12px}.terminal-row p{margin:0 0 4px;font-size:12px}.terminal-row small{color:#718096}.terminal-row pre{margin:0 0 12px;color:#9fd8b7;white-space:pre-wrap}.terminal-box form{display:flex;align-items:center;gap:8px;border-top:1px solid #243244;padding:8px 10px}.terminal-box input{flex:1;border:0;outline:0;background:transparent;color:#fff}.terminal-box button{height:30px;padding:0 12px;border:1px solid #415168;border-radius:5px;background:#1d2a39;color:#fff}.task-list-panel table,.task-panel table{width:100%;border-collapse:collapse;font-size:12px}.task-panel th,.task-panel td{padding:11px 10px;border-bottom:1px solid #edf0f4;text-align:left}.task-list-panel tr.selected{background:#f5f8ff}.pass,.review{display:inline-flex;padding:3px 8px;border-radius:999px}.pass{background:#e7f7ef;color:#087553}.review{background:#fff1e8;color:#b54708}.link-btn{border:0;background:none;color:#2563eb;font-weight:700}.empty-state{padding:26px;text-align:center;color:#7b8490;background:#f8fafc;border-radius:8px}.result-layout{grid-template-columns:repeat(5,minmax(0,1fr))}.task-summary{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.task-summary div{padding-right:12px;border-right:1px solid #edf0f4}.task-summary span,.metric span,.compare-cards span,.spec-row span{display:block;font-size:10px;color:#7b8490;margin-bottom:5px}.task-summary strong{font-size:12px}.metric{background:#fff;border:1px solid #dfe4ea;border-radius:10px;padding:14px}.metric strong{font-size:20px}.pass-text{color:#087553}.review-text{color:#b54708}.heat-demo{display:grid;grid-template-columns:repeat(15,1fr);gap:3px}.heat-demo i{aspect-ratio:1;background:#2563eb;border-radius:2px}.compare-cards,.spec-row{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.compare-cards div,.spec-row div{padding:18px;background:#f8fafc;border-radius:8px}.compare-cards strong,.spec-row strong{font-size:22px}@media(max-width:1100px){.task-workspace{grid-template-columns:1fr}.result-layout{grid-template-columns:repeat(2,minmax(0,1fr))}.task-summary{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style>
